<section class="admin-head"><div><p class="eyebrow">Content Authority OS · v1.4.0</p><h1>Editorial CMS & Search Architecture</h1><p>Publish useful plant knowledge with explicit search intent, first-hand nursery evidence, expert review, redirects and sitemap coverage.</p></div><a class="btn primary" href="<?=e(url('/admin/cms/new'))?>">New content</a></section>
<section class="admin-card"><h2>Content</h2><div class="table-wrap"><table><thead><tr><th>Title</th><th>Type</th><th>Status</th><th>Quality</th><th>Route</th><th>Updated</th></tr></thead><tbody><?php foreach($items as $i): $q=growth_content_quality($i);?><tr><td><a href="<?=e(url('/admin/cms/'.$i['guid']))?>"><?=e($i['title'])?></a></td><td><?=e($i['type'])?></td><td><?=e($i['status'])?></td><td><b class="<?=$q['score']>=$q['publish_threshold']?'ok':'warn'?>"><?=e((string)$q['score'])?>/100</b></td><td><?=e(cms_content_route($i))?></td><td><?=e(substr($i['updated_at'],0,16))?></td></tr><?php endforeach;?></tbody></table></div><?php if(!$items):?><p class="empty-state">No editorial content yet. Start with high-intent guides backed by real nursery observations and images.</p><?php endif;?></section>
<div class="admin-grid two"><section class="admin-card"><h2>Reusable block</h2><form method="post" action="<?=e(url('/admin/cms/block'))?>" class="stack"><?=csrf_field()?><label>Key<input name="key" placeholder="care-note" required></label><label>Title<input name="title"></label><label>Body<textarea name="body" rows="6" required></textarea></label><button class="btn outline">Save block</button></form><p>Embed using <code>[[block:care-note]]</code>.</p><ul><?php foreach($blocks as $b):?><li><strong><?=e($b['key'])?></strong> — <?=e($b['title'])?></li><?php endforeach;?></ul></section>
<section class="admin-card"><h2>Redirect</h2><form method="post" action="<?=e(url('/admin/cms/redirect'))?>" class="stack"><?=csrf_field()?><label>From<input name="from" placeholder="/old-path" required></label><label>To<input name="to" placeholder="/new-path" required></label><label>Code<select name="code"><option>301</option><option>302</option></select></label><button class="btn outline">Add redirect</button></form><ul><?php foreach($redirects as $r):?><li><?=e($r['code'].' '.$r['from'].' → '.$r['to'])?></li><?php endforeach;?></ul></section></div>
